export function getPPCTForSportAndGrade(sportKey: SportKey, grade: GradeLevel): PPCTRow[] {
  const sportData = ALL_PPCT_DATABASE[sportKey];
  if (sportData && sportData[grade]) {
    return sportData[grade];
  }
  if (sportData && sportData['10']) {
    return sportData['10'];
  }
  return ALL_PPCT_DATABASE['bong-ro']?.['10'] || [];
}

export function getPPCTForSport(sportKey: SportKey, grade: GradeLevel = '10'): PPCTRow[] {
  return getPPCTForSportAndGrade(sportKey, grade);
}

// Khung PPCT mặc định (Bóng chuyền & Bóng rổ) cho khả năng tương thích ngược
export const FULL_PPCT_70_PERIODS: PPCTRow[] = ALL_PPCT_DATABASE['bong-chuyen']?.['12'] || ALL_PPCT_DATABASE['bong-chuyen']?.['10'] || [];
export const FULL_PPCT_BASKETBALL_70_PERIODS: PPCTRow[] = ALL_PPCT_DATABASE['bong-ro']?.['10'] || [];

// Helper tạo LessonItem tự động từ bất kỳ hàng PPCT nào
export function createLessonFromPPCTRow(row: PPCTRow): LessonItem {
  const sportKey = row.sportKey;
  const grade = row.grade;
  const period = row.period;
  
  let defaultSvg = 'court-formation';
  let defaultImgTitle = 'Sơ đồ tổ chức đội hình và phân luồng sân tập';
  let defaultImgCaption = 'Bố trí 4 hàng so le cự ly 2m, có trạm giảm tải cho học sinh thừa cân/bệnh nền nhẹ gần giáo viên.';

  if (sportKey === 'bong-ro') {
    defaultSvg = 'basketball-shoot';
    defaultImgTitle = 'Kỹ thuật ném rổ Parabol & Đội hình tập luyện';
    defaultImgCaption = 'Mô phỏng tư thế tay chữ L, quỹ đạo góc phóng 48° - 52° và sơ đồ phân luồng luyện tập an toàn.';
  } else if (sportKey === 'bong-chuyen') {
    if (row.lessonTitle.toLowerCase().includes('phát bóng')) {
      defaultSvg = 'volleyball-serve-low';
      defaultImgTitle = 'Kỹ thuật phát bóng & Quỹ đạo bóng qua lưới';
      defaultImgCaption = 'Tư thế đứng nghiêng với lưới, cườm tay tiếp xúc tâm bóng đưa bóng qua mép lưới.';
    } else {
      defaultSvg = 'volleyball-pass-high';
      defaultImgTitle = 'Kỹ thuật chuyền đón bóng & Hoãn xung sinh cơ';
      defaultImgCaption = 'Bàn tay mở hình phễu trước trán 15-20cm, gối khuỵu hạ thấp trọng tâm đón bóng êm ái.';
    }
  } else if (sportKey === 'cau-long') {
    defaultSvg = 'badminton-court';
    defaultImgTitle = 'Sơ đồ sân cầu lông & Bộ bước di chuyển';
    defaultImgCaption = 'TTCB trung tâm, bao quát 4 góc sân với bộ bước trượt và bước chéo giảm chấn khớp gối.';
  }

  return {
    id: `${sportKey}-g${grade}-p${period}`,
    title: row.lessonTitle,
    classRef: `Khối ${grade} - Tuần ${row.week}, Tiết ${period}`,
    sgkRef: `SGK GDTC ${grade} (KNTT) • ${row.theme}`,
    grade: row.grade,
    sportKey: row.sportKey,
    periodNumber: period,
    durationMinutes: 45,
    week: row.week,
    objective: `Nắm vững yêu cầu cần đạt của bài: "${row.lessonTitle}"; thực hiện tương đối đúng yếu lĩnh động tác; biết vận dụng vào thực tế thi đấu và rèn luyện thể lực.`,
    newKnowledge: `Phân tích cấu trúc sinh cơ học động tác "${row.lessonTitle}"; các lỗi sai cơ bản cần khắc phục và nguyên tắc an toàn sân bãi.`,
    practice: `Luyện tập mô phỏng không bóng/cầu; tập theo cặp đôi cự ly chuẩn; thực hành tình huống thi đua và trò chơi vận động nhóm.`,
    aiDigital: `Sử dụng camera AI slow-motion 60fps quay phân tích góc gập khớp gối, đường vung tay và đo nhịp tim hồi tĩnh sau vận động.`,
    safetyNote: `Kiểm tra bề mặt sân trước giờ tập; nhóm thừa cân/đau khớp thực hiện giảm tải khối lượng bài tập theo phác đồ cá nhân hóa.`,
    assessmentCriteria: `Thực hiện đúng kỹ thuật tối thiểu 3/5 lần; tự giác rèn luyện và trung thực trong đánh giá đồng đẳng.`,
    images: [
      {
        id: `img-${sportKey}-${grade}-${period}`,
        title: defaultImgTitle,
        caption: defaultImgCaption,
        type: 'biomechanics',
        svgType: defaultSvg
      }
    ]
  };
}

// Hàm lấy toàn bộ danh sách bài học KHBD cho Phân môn & Khối lớp
export function getLessonsForSportAndGrade(sportKey: SportKey, grade: GradeLevel): LessonItem[] {
  const ppctList = getPPCTForSportAndGrade(sportKey, grade);
  return ppctList.map(row => createLessonFromPPCTRow(row));
}

